56	  if (error && !isLoading) {
57	    toast.error(t("message.user-not-found"));
58	  }
59	
60	  const memoFilter = useMemoFilters({
61	    creatorName: user?.name,
62	    includeShortcuts: false,
63	    includePinned: true,
64	  });
